/**
 * 奶蛙 (Naiwa) — sprite-sheet desktop pet for the Harness Web UI.
 *
 * The artwork is the Codex-App pet sheet (`assets/spritesheet.webp`):
 * 11 rows x 8 columns, 192x208 per cell, transparent background, feet anchored
 * at y=202 in every cell. Frames are stepped by writing `background-position`,
 * never by re-rendering: one rAF loop owns the sheet, React owns only the
 * position, the bubble and the drag state.
 *
 * The sheet is embedded as a data URI at the bottom of this file so the pet
 * needs no Host route and no second request; the binary lives in `assets/`
 * for regeneration.
 *
 * DEBUG renders an on-screen diagnostic panel above the pet. This build of the
 * desktop app ships without DevTools, so the panel is the debugging surface:
 * a moving frame counter proves the rAF loop is alive, VERSION proves whether
 * the page actually loaded the new module, and captured window errors replace
 * the console nobody can open.
 */
window.__ModuleLoader__.load({
  id: '@local/naiwa-pet',
  factory(require) {
    const React = require('react');
    const h = React.createElement;

    const NS = 'naiwa-pet';
    const STORE_KEY = 'naiwa-pet:pos:v2';
    const VERSION = '2.1.0';
    const DEBUG = true;

    /* ------------------------------------------------------------ geometry */

    const COLS = 8;
    const ROWS = 11;
    const CELL_W = 112;
    const CELL_H = 121; // round(112 * 208 / 192); the sheet is scaled to 8*112 x 11*121

    /**
     * Row map, read off the sheet's frame contents and per-row frame counts:
     *   0 idle (7)   1 walk (8)   2 run (8)     3 wave (4)    4 laugh (5)
     *   5 settle (8) 6 stand (6)  7 think (6)   8 smug (6)    9 turn (8)
     *  10 profile (8)
     * Only the rows the behaviour actually uses are listed.
     */
    const ACTIONS = {
      idle: { row: 0, frames: 7, fps: 7 },
      walk: { row: 1, frames: 8, fps: 13 },
      wave: { row: 3, frames: 4, fps: 9, once: true },
      laugh: { row: 4, frames: 5, fps: 11, once: true },
      think: { row: 7, frames: 6, fps: 5 },
      smug: { row: 8, frames: 6, fps: 6 },
      settle: { row: 5, frames: 8, fps: 7, once: true },
    };

    const REST_AFTER = 7000;
    const THINK_AFTER = 45000;
    const SLEEP_AFTER = 100000;

    /* ---------------------------------------------------------------- style */

    const CSS = `
.nw-pet { position: fixed; z-index: 45; pointer-events: none; }
.nw-tilt { width: 100%; height: 100%; transition: transform 0.18s ease-out; }
.nw-pet.is-dragging .nw-tilt { transition: none; }
.nw-hit {
  position: relative;
  width: 100%;
  height: 100%;
  pointer-events: auto;
  cursor: grab;
  touch-action: none;
  user-select: none;
  -webkit-user-select: none;
  -webkit-tap-highlight-color: transparent;
  border-radius: 14px;
  outline: none;
}
.nw-pet.is-dragging .nw-hit { cursor: grabbing; }
.nw-hit:focus-visible { outline: 2px solid var(--dsw-alias-brand-primary); outline-offset: 3px; }
.nw-sprite {
  width: 100%;
  height: 100%;
  background-repeat: no-repeat;
  background-size: ${COLS * CELL_W}px ${ROWS * CELL_H}px;
  background-position: 0 0;
  will-change: background-position;
  filter: drop-shadow(0 6px 9px rgba(0, 0, 0, 0.18));
}
.nw-bubble {
  position: absolute;
  left: 50%;
  bottom: calc(100% - 6px);
  transform: translateX(-50%);
  max-width: 240px;
  padding: 7px 11px;
  border-radius: 11px;
  white-space: nowrap;
  font-size: 12px;
  line-height: 1.3;
  color: var(--dsw-alias-label-primary);
  background: var(--dsw-alias-bg-overlay);
  border: 1px solid var(--dsw-alias-border-l1);
  box-shadow: 0 6px 18px rgba(0, 0, 0, 0.14);
  pointer-events: none;
  animation: nw-bubble-in 0.2s ease-out;
}
.nw-bubble::after {
  content: "";
  position: absolute;
  left: 50%;
  top: 100%;
  width: 9px;
  height: 9px;
  margin-top: -5px;
  transform: translateX(-50%) rotate(45deg);
  background: var(--dsw-alias-bg-overlay);
  border-right: 1px solid var(--dsw-alias-border-l1);
  border-bottom: 1px solid var(--dsw-alias-border-l1);
}
@keyframes nw-bubble-in {
  from { opacity: 0; transform: translate(-50%, 4px) scale(0.94); }
  to { opacity: 1; transform: translate(-50%, 0) scale(1); }
}
.nw-diag {
  position: absolute;
  left: 0;
  top: -52px;
  max-width: 210px;
  padding: 4px 7px;
  border-radius: 6px;
  white-space: pre;
  font: 10px/1.4 ui-monospace, SFMono-Regular, Menlo, monospace;
  color: var(--dsw-alias-label-secondary);
  background: var(--dsw-alias-bg-overlay);
  border: 1px solid var(--dsw-alias-border-l1);
  pointer-events: none;
  opacity: 0.92;
}
@media (prefers-reduced-motion: reduce) {
  .nw-tilt { transition: none; }
}
`;

    /* --------------------------------------------------------------- locale */

    const EN = {
      label: 'Naiwa',
      'say.hi': 'Naiwa is here.',
      'say.idle1': 'Careful, that tickles.',
      'say.idle2': 'Still here. Still yellow.',
      'say.idle3': "Take a breath. You're doing fine.",
      'say.laugh': 'Hehe — you got me.',
      'say.drop': 'Oof. Comfy enough.',
      'say.sleep': 'Mmm… five more minutes.',
      'say.wake': "I wasn't asleep. I was thinking.",
    };

    const ZH = {
      label: '奶蛙',
      'say.hi': '奶蛙在这儿。',
      'say.idle1': '戳我干嘛呀。',
      'say.idle2': '我一直都在，不用找我。',
      'say.idle3': '歇会儿吧，你已经很努力了。',
      'say.laugh': '嘿嘿，被你发现了。',
      'say.drop': '呼，落地了。',
      'say.sleep': '再让我趴五分钟……',
      'say.wake': '我没睡，我在思考。',
    };

    /* -------------------------------------------------------------- helpers */

    function clampPos(p) {
      const maxX = Math.max(4, window.innerWidth - CELL_W - 4);
      const maxY = Math.max(4, window.innerHeight - CELL_H - 4);
      return { x: Math.min(Math.max(4, p.x), maxX), y: Math.min(Math.max(4, p.y), maxY) };
    }

    function defaultPos() {
      return clampPos({ x: window.innerWidth - CELL_W - 40, y: window.innerHeight - CELL_H - 110 });
    }

    function readPos() {
      try {
        const raw = window.localStorage.getItem(STORE_KEY);
        if (!raw) return defaultPos();
        const seen = JSON.parse(raw);
        if (!seen || typeof seen.x !== 'number' || typeof seen.y !== 'number') return defaultPos();
        return clampPos({ x: seen.x, y: seen.y });
      } catch (err) {
        return defaultPos();
      }
    }

    function writePos(p) {
      try {
        window.localStorage.setItem(STORE_KEY, JSON.stringify({ x: Math.round(p.x), y: Math.round(p.y) }));
      } catch (err) {
        /* storage unavailable: the pet simply forgets where it was */
      }
    }

    /* ------------------------------------------------------------- component */

    function makePet(t) {
      return function NaiwaPet() {
        const [pos, setPos] = React.useState(readPos);
        const [bubble, setBubble] = React.useState(null);
        const [dragging, setDragging] = React.useState(false);
        const [tilt, setTilt] = React.useState(0);
        const [facing, setFacing] = React.useState(1);

        const spriteRef = React.useRef(null);
        const diagRef = React.useRef(null);
        const errRef = React.useRef('');
        const posRef = React.useRef(pos);
        const dragRef = React.useRef(null);
        const animRef = React.useRef({ name: 'idle', start: performance.now(), frame: -1, done: false, opts: null });
        const idleAtRef = React.useRef(Date.now());
        const fallRaf = React.useRef(0);
        const walkRaf = React.useRef(0);
        const bubbleTimer = React.useRef(0);
        posRef.current = pos;

        const paint = (row, index) => {
          const el = spriteRef.current;
          if (el) el.style.backgroundPosition = (-index * CELL_W) + 'px ' + (-row * CELL_H) + 'px';
        };

        const setAction = (name, opts) => {
          const spec = ACTIONS[name];
          if (!spec) return;
          animRef.current = { name: name, start: performance.now(), frame: -1, done: false, opts: opts || null };
        };

        const say = (key, ms) => {
          setBubble({ key: key, id: Math.random() });
          if (bubbleTimer.current) clearTimeout(bubbleTimer.current);
          bubbleTimer.current = setTimeout(() => setBubble(null), ms || 3000);
        };

        const touchIdle = () => { idleAtRef.current = Date.now(); };

        /* one rAF loop owns frame stepping for every action */
        React.useEffect(() => {
          let raf = 0;
          let lastDiag = 0;
          let ticks = 0;
          const tick = (now) => {
            const a = animRef.current;
            const spec = ACTIONS[a.name];
            if (spec) {
              const raw = Math.floor((now - a.start) / (1000 / spec.fps));
              const index = spec.once ? Math.min(raw, spec.frames - 1) : raw % spec.frames;
              if (index !== a.frame) {
                a.frame = index;
                paint(spec.row, index);
              }
              if (spec.once && raw >= spec.frames && !a.done) {
                a.done = true;
                if (a.opts && a.opts.done) a.opts.done();
              }
            }
            ticks += 1;
            if (DEBUG && diagRef.current && now - lastDiag > 400) {
              lastDiag = now;
              diagRef.current.textContent =
                'v' + VERSION + '  live ' + ticks + '\n' +
                a.name + '  frame ' + a.frame + '/' + (spec ? spec.frames : '?') + '\n' +
                'x' + Math.round(posRef.current.x) + ' y' + Math.round(posRef.current.y) +
                (errRef.current ? '\nERR ' + errRef.current : '');
            }
            raf = requestAnimationFrame(tick);
          };
          raf = requestAnimationFrame(tick);
          return () => cancelAnimationFrame(raf);
        }, []);

        /* the console is unavailable in this build; surface errors on screen */
        React.useEffect(() => {
          if (!DEBUG) return undefined;
          const record = (message) => { errRef.current = String(message).slice(0, 90); };
          const onError = (event) => record((event && event.message) || 'error');
          const onReject = (event) => {
            const reason = event && event.reason;
            record((reason && reason.message) || reason || 'rejection');
          };
          window.addEventListener('error', onError);
          window.addEventListener('unhandledrejection', onReject);
          return () => {
            window.removeEventListener('error', onError);
            window.removeEventListener('unhandledrejection', onReject);
          };
        }, []);

        React.useEffect(() => {
          setPos((p) => clampPos(p));
          const onResize = () => setPos((p) => clampPos(p));
          window.addEventListener('resize', onResize);
          return () => {
            window.removeEventListener('resize', onResize);
            if (fallRaf.current) cancelAnimationFrame(fallRaf.current);
            if (walkRaf.current) cancelAnimationFrame(walkRaf.current);
            if (bubbleTimer.current) clearTimeout(bubbleTimer.current);
          };
        }, []);

        const settleDown = () => {
          touchIdle();
          if (fallRaf.current || walkRaf.current) return;
          setAction('settle');
        };

        const beginWander = () => {
          const from = posRef.current.x;
          const maxX = Math.max(4, window.innerWidth - CELL_W - 4);
          const dir = Math.random() < 0.5 ? -1 : 1;
          const target = Math.min(maxX, Math.max(4, from + dir * (70 + Math.random() * 150)));
          if (Math.abs(target - from) < 30) return;
          setFacing(target > from ? 1 : -1);
          setAction('walk');
          const t0 = performance.now();
          const duration = Math.abs(target - from) * 11;
          const step = (now) => {
            const k = Math.min(1, (now - t0) / duration);
            const x = from + (target - from) * k;
            setPos((p) => ({ x: x, y: p.y }));
            if (k < 1) {
              walkRaf.current = requestAnimationFrame(step);
            } else {
              walkRaf.current = 0;
              setFacing(1);
              setAction('idle');
              writePos({ x: target, y: posRef.current.y });
            }
          };
          walkRaf.current = requestAnimationFrame(step);
        };

        /* autonomous behaviour: wander, think, doze off */
        React.useEffect(() => {
          const id = setInterval(() => {
            if (dragRef.current || fallRaf.current || walkRaf.current) return;
            const name = animRef.current.name;
            if (name === 'wave' || name === 'laugh') return;
            const idleFor = Date.now() - idleAtRef.current;
            if (idleFor < REST_AFTER) {
              if (name !== 'idle') setAction('idle');
              return;
            }
            if (idleFor > SLEEP_AFTER) {
              if (name !== 'settle') { settleDown(); say('say.sleep', 4000); }
              return;
            }
            if (name === 'settle') return;
            if (name === 'think') {
              if (idleFor > THINK_AFTER) setAction('idle');
              return;
            }
            if (name !== 'idle') return;
            if (Math.random() < 0.14) {
              if (Math.random() < 0.55) beginWander();
              else setAction('think');
            }
          }, 1200);
          return () => clearInterval(id);
        }, []);

        const poke = () => {
          touchIdle();
          if (animRef.current.name === 'settle') { setAction('idle'); say('say.wake'); return; }
          if (Math.random() < 0.55) {
            setAction('wave', { done: () => setAction('idle') });
            say('say.hi');
          } else {
            setAction('laugh', { done: () => setAction('idle') });
            say('say.laugh');
          }
        };

        const fall = (vx, vy) => {
          const floor = Math.max(4, window.innerHeight - CELL_H - 4);
          const maxX = Math.max(4, window.innerWidth - CELL_W - 4);
          let px = posRef.current.x;
          let py = posRef.current.y;
          let sx = vx;
          let sy = vy;
          const step = () => {
            sy += 1.15;
            sx *= 0.97;
            px += sx;
            py += sy;
            if (px < 4) { px = 4; sx = -sx * 0.5; }
            if (px > maxX) { px = maxX; sx = -sx * 0.5; }
            if (py >= floor) {
              py = floor;
              setPos({ x: px, y: py });
              writePos({ x: px, y: py });
              fallRaf.current = 0;
              setAction('idle');
              say('say.drop', 2000);
              return;
            }
            setPos({ x: px, y: py });
            fallRaf.current = requestAnimationFrame(step);
          };
          fallRaf.current = requestAnimationFrame(step);
        };

        const onDown = (event) => {
          if (event.button > 0) return;
          if (fallRaf.current) { cancelAnimationFrame(fallRaf.current); fallRaf.current = 0; }
          if (walkRaf.current) { cancelAnimationFrame(walkRaf.current); walkRaf.current = 0; }
          const current = posRef.current;
          dragRef.current = {
            id: event.pointerId,
            dx: event.clientX - current.x,
            dy: event.clientY - current.y,
            x0: event.clientX,
            y0: event.clientY,
            moved: false,
            vx: 0,
            vy: 0,
            lx: event.clientX,
            ly: event.clientY,
          };
          try { event.currentTarget.setPointerCapture(event.pointerId); } catch (err) { /* ignore */ }
          setDragging(true);
          setTilt(0);
          setAction('idle');
          touchIdle();
        };

        const onMove = (event) => {
          const drag = dragRef.current;
          if (!drag || drag.id !== event.pointerId) return;
          if (!drag.moved && (Math.abs(event.clientX - drag.x0) > 4 || Math.abs(event.clientY - drag.y0) > 4)) {
            drag.moved = true;
          }
          drag.vx = event.clientX - drag.lx;
          drag.vy = event.clientY - drag.ly;
          drag.lx = event.clientX;
          drag.ly = event.clientY;
          if (drag.moved) setTilt(Math.max(-13, Math.min(13, drag.vx * 2.4)));
          setPos(clampPos({ x: event.clientX - drag.dx, y: event.clientY - drag.dy }));
        };

        const onUp = (event) => {
          const drag = dragRef.current;
          if (!drag || drag.id !== event.pointerId) return;
          dragRef.current = null;
          setDragging(false);
          setTilt(0);
          touchIdle();
          if (!drag.moved) { poke(); return; }
          fall(drag.vx * 0.55, drag.vy * 0.35);
        };

        const onKey = (event) => {
          if (event.key !== 'Enter' && event.key !== ' ') return;
          event.preventDefault();
          poke();
        };

        const classes = ['nw-pet'];
        if (dragging) classes.push('is-dragging');

        return h(
          'div',
          {
            className: classes.join(' '),
            style: { left: pos.x + 'px', top: pos.y + 'px', width: CELL_W + 'px', height: CELL_H + 'px' },
          },
          h('style', { key: 'style' }, CSS),
          DEBUG ? h('div', { key: 'diag', className: 'nw-diag', ref: diagRef }, 'booting…') : null,
          h(
            'div',
            { key: 'tilt', className: 'nw-tilt', style: { transform: tilt ? 'rotate(' + tilt.toFixed(2) + 'deg)' : 'none' } },
            h(
              'div',
              {
                className: 'nw-hit',
                role: 'button',
                tabIndex: 0,
                'aria-label': t('label'),
                onPointerDown: onDown,
                onPointerMove: onMove,
                onPointerUp: onUp,
                onPointerCancel: onUp,
                onKeyDown: onKey,
              },
              h('div', {
                className: 'nw-sprite',
                ref: spriteRef,
                style: facing < 0
                  ? { backgroundImage: SPRITE_STYLE.backgroundImage, transform: 'scaleX(-1)' }
                  : SPRITE_STYLE,
              }),
            ),
          ),
          bubble ? h('div', { key: 'bubble', className: 'nw-bubble' }, t(bubble.key)) : null,
        );
      };
    }

    /* ---------------------------------------------------------------- payload */

    /*
     * 1536x2288 WebP, re-encoded from the Codex-App pet sheet at q90.
     * Kept last so the logic above stays readable and easy to edit.
     * Same object identity every render, so React never re-diffs a 550 KiB
     * inline style while the pet is walking.
     */
    const SPRITE = 'data:image/webp;base64,';
    const SPRITE_STYLE = { backgroundImage: 'url("' + SPRITE + '")' };

    /* ----------------------------------------------------------------- apply */

    return {
      inject: ['slots', 'locale'],
      apply(ctx) {
        const offs = [];
        const addDict = (locale, dict) => {
          try {
            const off = ctx.locale.register(NS, locale, dict);
            if (typeof off === 'function') offs.push(off);
          } catch (err) {
            /* a previous activation of this bundle already registered the namespace */
          }
        };
        addDict('en', EN);
        addDict('zh-CN', ZH);
        addDict('zh', ZH);
        ctx.effect(() => () => {
          for (const off of offs) {
            try { off(); } catch (err) { /* ignore */ }
          }
        });

        ctx.slots.inject('shell.overlay', () =>
          ctx.slots.register(
            { name: 'shell.overlay', id: 'naiwa-pet', order: 60 },
            makePet(ctx.locale.bind(NS)),
          ),
        );
      },
    };
  },
});
